import React, { useState } from 'react';
import {
  Box,
  Container,
  Typography,
  TextField,
  Button,
  Paper,
  Avatar,
  Grid,
  Link,
  Alert,
  FormControlLabel,
  Checkbox,
} from '@mui/material';
import LoginIcon from '@mui/icons-material/Login';
import { styled } from '@mui/material/styles';

const StyledPaper = styled(Paper)(({ theme }) => ({
  marginTop: theme.spacing(4),
  marginBottom: theme.spacing(4),
  padding: theme.spacing(4),
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  backgroundColor: 'rgba(255, 255, 255, 0.9)',
  backdropFilter: 'blur(10px)',
  maxWidth: '450px',
  width: '100%',
}));

const StyledAvatar = styled(Avatar)(({ theme }) => ({
  margin: theme.spacing(1),
  backgroundColor: theme.palette.primary.main,
  width: theme.spacing(7),
  height: theme.spacing(7),
}));

const StyledContainer = styled(Container)({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  minHeight: 'calc(100vh - 64px)', // Subtract AppBar height
});

const inputStyles = {
  '& .MuiOutlinedInput-root': {
    height: '65px',
    fontSize: '1.2rem'
  },
  '& .MuiInputLabel-root': {
    fontSize: '1.2rem',
    transform: 'translate(14px, 21px) scale(1)',
    '&.Mui-focused, &.MuiFormLabel-filled': {
      transform: 'translate(14px, -9px) scale(0.75)'
    }
  },
  width: '100%',
  mb: 2
};

const Login = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: '',
  });

  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevState => ({
      ...prevState,
      [name]: value
    }));
    setError('');
  };

  const validateForm = () => {
    if (!formData.email || !formData.password) {
      setError('All fields are required');
      return false;
    }

    if (!formData.email.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)) {
      setError('Please enter a valid email address');
      return false;
    }

    return true;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    try {
      // Here you would typically make an API call to your backend
      console.log('Login attempt:', formData);
      setSuccess(true);
      setError('');

      // Reset form
      setFormData({
        email: '',
        password: '',
      });
    } catch (err) {
      setError('Invalid email or password');
    }
  };

  return (
    <StyledContainer>
      <StyledPaper elevation={6}>
        <StyledAvatar>
          <LoginIcon sx={{ fontSize: 32 }} />
        </StyledAvatar>
        <Typography component="h1" variant="h4" gutterBottom sx={{ fontWeight: 500 }}>
          Login
        </Typography>
        {error && (
          <Alert severity="error" sx={{ width: '100%', mb: 2 }}>
            {error}
          </Alert>
        )}
        {success && (
          <Alert severity="success" sx={{ width: '100%', mb: 2 }}>
            Login successful!
          </Alert>
        )}
        <Box component="form" onSubmit={handleSubmit} sx={{ mt: 3, width: '100%' }}>
          <Grid container spacing={2} sx={{ 
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
          }}>
            <Grid item xs={12} sm={10}>
              <TextField
                name="email"
                required
                fullWidth
                label="Email Address"
                type="email"
                value={formData.email}
                onChange={handleChange}
                variant="outlined"
                autoFocus
                sx={inputStyles}
              />
            </Grid>
            <Grid item xs={12} sm={10}>
              <TextField
                name="password"
                required
                fullWidth
                label="Password"
                type="password"
                value={formData.password}
                onChange={handleChange}
                variant="outlined"
                sx={inputStyles}
              />
              <Box sx={{ 
                display: 'flex', 
                justifyContent: 'space-between',
                alignItems: 'center',
                mt: 1
              }}>
                <Link 
                  href="/forgot-password" 
                  variant="body2" 
                  sx={{ 
                    textDecoration: 'none',
                  }}
                >
                  Forgot Password?
                </Link>
                <FormControlLabel
                  control={
                    <Checkbox
                      color="primary"
                      onChange={(e) => console.log('Remember me:', e.target.checked)}
                    />
                  }
                  label="Remember me"
                />
              </Box>
            </Grid>
          </Grid>
          <Button
            type="submit"
            variant="contained"
            size="large"
            sx={{ 
              mt: 4, 
              mb: 2,
              py: 1.5,
              fontSize: '1.1rem',
              width: '66.67%',
              display: 'block',
              margin: '2rem auto',
            }}
          >
            Login
          </Button>
          <Grid container justifyContent="center" spacing={2}>
            <Grid item>
              <Link href="/signup" variant="body1" sx={{ textDecoration: 'none' }}>
                Don't have an account? Sign Up
              </Link>
            </Grid>
            <Grid item>
              <Link href="/admin-login" variant="body1" sx={{ textDecoration: 'none' }}>
                Admin Login
              </Link>
            </Grid>
          </Grid>
        </Box>
      </StyledPaper>
    </StyledContainer>
  );
};

export default Login;
